DROP TABLE IF EXISTS `harbor_project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `harbor_project` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `image_name` varchar(100) NOT NULL COMMENT '镜像名称',
  `create_resource` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0 - NOTEBOOK模型管理  1- ALGORITHM算法管理',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user_id` bigint(20) DEFAULT NULL COMMENT '创建用户ID',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_user_id` bigint(20) DEFAULT NULL COMMENT '更新用户ID',
  `deleted` bit(1) DEFAULT b'0' COMMENT '0正常，1已删除',
  `sync_status` tinyint(1) DEFAULT '0' COMMENT '同步状态(默认为0，同步成功为1)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `image_name` (`image_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='harbor project表';
