  `resource_name` varchar(64) NOT NULL COMMENT '资源名称',
  `env` varchar(32) DEFAULT NULL COMMENT '环境',
  `business` varchar(32) DEFAULT NULL COMMENT '所属业务模块',
  `create_user_id` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '删除(0正常，1已删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `kind_namespace_name_uniq` (`kind`,`namespace`,`name`) COMMENT '资源唯一',
  KEY `name` (`name`),
  KEY `resource_name` (`resource_name`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='k8s资源表';
