DROP TABLE IF EXISTS `k8s_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `k8s_task` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `namespace` varchar(64) NOT NULL COMMENT '命名空间',
  `resource_name` varchar(64) NOT NULL COMMENT '资源名称',
  `task_yaml` json NOT NULL COMMENT '资源清单',
  `business` varchar(32) DEFAULT NULL COMMENT '所属业务模块',
  `apply_unix_time` bigint(20) NOT NULL DEFAULT '0' COMMENT '资源创建unix时间(精确到秒)',
  `apply_display_time` timestamp NULL DEFAULT NULL COMMENT '资源创建展示时间',
  `apply_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态(0无需操作，1未创建，2已创建)',
  `stop_unix_time` bigint(20) NOT NULL DEFAULT '0' COMMENT '资源停止unix时间(精确到秒)',
  `stop_display_time` timestamp NULL DEFAULT NULL COMMENT '资源停止展示时间',
  `stop_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态(0无需操作，1未停止，2已停止)',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user_id` bigint(20) DEFAULT '0' COMMENT '创建用户ID',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_user_id` bigint(20) DEFAULT '0' COMMENT '更新用户ID',
  `deleted` bit(1) DEFAULT b'0' COMMENT '0正常，1已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `resource_name_namespace` (`resource_name`,`namespace`) COMMENT '唯一索引',
  KEY `apply_unix_time` (`apply_unix_time`),
  KEY `stop_unix_time` (`stop_unix_time`),
  KEY `apply_status` (`apply_status`) USING BTREE,
  KEY `stop_status` (`stop_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='k8s任务表';
