--
-- Table structure for table `model_opt_build_in`
--

DROP TABLE IF EXISTS `model_opt_build_in`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `model_opt_build_in` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` tinyint(4) NOT NULL COMMENT '算法类型（0-剪枝，1-蒸馏，2-量化）',
  `algorithm` varchar(255) DEFAULT NULL COMMENT '算法名称',
  `algorithm_path` varchar(255) DEFAULT NULL COMMENT '算法路径',
  `dataset` varchar(255) DEFAULT NULL COMMENT '数据集名称',
  `dataset_path` varchar(255) DEFAULT NULL COMMENT '数据集路径',
  `model` varchar(255) DEFAULT NULL COMMENT '模型名称',
  `model_path` varchar(255) DEFAULT NULL COMMENT '模型路径',
  `create_user_id` bigint(20) DEFAULT NULL COMMENT '创建用户ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) DEFAULT NULL COMMENT '更新用户ID',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) DEFAULT b'0' COMMENT '0正常，1已删除',
