  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` bigint(20) NOT NULL COMMENT '任务Id',
  `task_name` varchar(127) DEFAULT NULL COMMENT '任务名称',
  `is_built_in` bit(1) DEFAULT NULL COMMENT '是否内置',
  `model_id` bigint(20) DEFAULT NULL COMMENT '模型id',
  `model_name` varchar(255) DEFAULT NULL COMMENT '模型名称',
  `model_address` varchar(255) DEFAULT NULL COMMENT '模型路径',
  `algorithm_id` bigint(20) DEFAULT NULL COMMENT '优化算法id',
  `algorithm_type` tinyint(4) DEFAULT NULL COMMENT '优化算法类型',
  `algorithm_name` varchar(255) DEFAULT NULL COMMENT '算法路径',
  `algorithm_path` varchar(255) DEFAULT NULL COMMENT '使用类型 0-内置 1-我的',
  `dataset_id` bigint(20) DEFAULT NULL COMMENT '数据集id',
  `dataset_name` varchar(255) DEFAULT NULL COMMENT '数据集名称',
  `dataset_path` varchar(255) DEFAULT NULL COMMENT '数据集路径',
  `start_time` datetime DEFAULT NULL COMMENT '任务实例开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '任务实例结束时间',
  `output_model_dir` varchar(255) DEFAULT '0' COMMENT '输出模型路径',
  `log_path` varchar(255) DEFAULT NULL COMMENT '日志地址',
  `status` varchar(8) NOT NULL DEFAULT '-1' COMMENT '-1-等待中,0-进行中,1-已完成,2-已取消,3-执行失败',
  `status_detail` json DEFAULT NULL COMMENT '状态对应的详情信息',
  `command` text COMMENT '运行命令',
  `params` json DEFAULT NULL COMMENT '运行参数',
  `opt_result_before` mediumtext COMMENT '模型优化前性能参数',
  `opt_result_json_path_before` varchar(255) DEFAULT NULL COMMENT '模型优化前性能参数json文件路径',
  `opt_result_after` mediumtext COMMENT '模型优化后性能参数',
  `opt_result_json_path_after` varchar(255) DEFAULT NULL COMMENT '模型优化后性能参数json文件路径',
  `origin_user_id` bigint(20) DEFAULT NULL COMMENT '资源用有人ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user_id` bigint(20) DEFAULT NULL COMMENT '创建人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_user_id` bigint(20) DEFAULT NULL COMMENT '修改人',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标识：0-未删除，1-删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `task_id` (`task_id`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
